"#pragma arguments
float u_grayMix;
float4 u_tint;
#pragma body
float gray = dot(_output.color.rgb, float3(0.299, 0.587, 0.114));
_output.color.rgb = mix(_output.color.rgb, float3(gray, gray, gray), u_grayMix);
_output.color.rgb = mix(_output.color.rgb, u_tint.rgb * (0.35 + 0.9 * gray), u_tint.a);"
